import type { Product } from '../types';
import SLIM from './products.slim.json';

/**
 * Compact catalogue for everything that runs in the browser (cards, filters, search, cart).
 * Generated by scripts/gen-slim-products.ts. Long descriptions, features, specs and the gallery live in
 * public/data/p/<slug>.json and are loaded only by product pages. Server code that needs the full
 * records imports ./products instead.
 */
type SlimRow = {
  s: string; b: string; n: string; c: string; p: number; m: string; w: number; g: string; u: string[]; z: string[];
  d: string; e: string; ne?: string; i?: string; im?: string; op?: number; t?: number; r?: number; kg?: number;
  py?: number; os?: number; fm?: string; rf?: number; col?: Product['colors'][number];
};

export const PRODUCTS: Product[] = (SLIM as unknown as SlimRow[]).map((r) => ({
  id: r.i ?? r.s,
  slug: r.s,
  brand: r.b,
  name_de: r.n,
  name_en: r.ne ?? r.n,
  description_de: r.d,
  description_en: r.e,
  category: r.c as Product['category'],
  price: r.p,
  originalPrice: r.op,
  motor: r.m as Product['motor'],
  motorDetails: '',
  torqueNm: r.t,
  batteryWh: r.w,
  rangeKm: r.r,
  weightKg: r.kg,
  gender: r.g as Product['gender'],
  useCases: r.u,
  isPreviousYear: r.py ? true : undefined,
  images: [r.im ?? `/images/products/${r.s}/main.webp`],
  sizes: r.z,
  colors: r.col ? [r.col] : [],
  features_de: r.rf ? ['riemenantrieb'] : [],
  features_en: [],
  inStock: !r.os,
  specs: { frameMaterial: r.fm ?? '', gears: '', brakes: '', fork: '', wheelSize: '' },
}));
